  "g"
);

const P5_CONSTANTS = [
  "WIDTH", "HEIGHT", "PI", "TWO_PI", "HALF_PI", "QUARTER_PI", "TAU", "EPSILON",
  "CENTER", "CORNER", "LEFT", "RIGHT", "TOP", "BOTTOM", "BASELINE", "TOP_LEFT",
