// Pre-build a map of {basename → absolute path} for every file under
// public/assets so we can resolve `/assets/<name>` references to local
// files and inline them as base64 data: URIs in the example strings.
const assetsRoot = path.join(tmpDir, ASSETS_DIR);
const assetByBasename = new Map();
if (fs.existsSync(assetsRoot)) {
  function walkAssets(dir) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walkAssets(full);
      } else {
        assetByBasename.set(entry.name, full);
      }
    }
  }
  walkAssets(assetsRoot);
  console.log(`Found ${assetByBasename.size} bundled asset files`);
} else {
  console.log("  No public/assets dir found — skipping asset inlining");
}

// Cache data: URIs by basename so repeated references to the same file
// (e.g. /assets/teapot.obj appears in many loadModel examples) only read
// + encode the file once.
const dataUriCache = new Map();
function getDataUri(basename) {
  if (dataUriCache.has(basename)) return dataUriCache.get(basename);
  const filePath = assetByBasename.get(basename);
  let uri = null;
  if (filePath) uri = buildDataUri(filePath);
  dataUriCache.set(basename, uri);
  return uri;
}

// Rewrite every `/assets/<name>` and `./<name>` reference in an example
// string to a `data:<mime>;base64,...` URI. Unresolved or skipped assets
// are left untouched (the example may fail in-preview but won't break
// the build). Returns the rewritten string.
function inlineAssets(code) {
  if (!assetByBasename.size) return code;
  let out = code;
  out = out.replace(ASSET_PATH_RE, (full, quote, name) => {
    const uri = getDataUri(name);
    return uri ? `${quote}${uri}${quote}` : full;
  });
  out = out.replace(RELATIVE_ASSET_RE, (full, quote, name) => {
    const uri = getDataUri(name);
    return uri ? `${quote}${uri}${quote}` : full;
  });
  return out;
}

