        <Polygon points="20,40 60,40 60,80 20,80" opacity={0.6} />
        <Line x1="30" y1="30" x2="20" y2="40" />
        <Line x1="70" y1="30" x2="60" y2="40" />
        <Line x1="70" y1="70" x2="60" y2="80" />
        <Line x1="30" y1="70" x2="20" y2="80" />
      </Svg>
    </Animated.View>
  );
}

// Ellipse helper for data stack (react-native-svg exports Ellipse but keep it simple).
function Ellipse(props: { cx: number; cy: number; rx: number; ry: number; stroke: string; strokeWidth: number }) {
  const { cx, cy, rx, ry, stroke, strokeWidth } = props;
